package com.oms.order.service;
import com.oms.common.tenant.TenantRouting;
import com.oms.common.task.ScopedWorkExecutor;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
/** Durable shop cursors and fixed windows. Immediate work and Quartz share the same leased path. */
@Service public class ExchangeSync {
    @Resource OrderRepository repository;
    @Resource ExchangeService exchanges;
    @Resource PlatformExchangeService platformExchanges;
    @Resource TenantRouting tenants;
    @Resource ExchangeExecution execution;
    @Resource ExchangeFlowAutomation automatic;
    private final ScopedWorkExecutor executor=new ScopedWorkExecutor("exchange");
    private final Set<String> active=ConcurrentHashMap.newKeySet();
    private final Set<String> requested=ConcurrentHashMap.newKeySet();
    TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    public Map<String,Object> poll(){int queued=0;for(String company:tenants.companies())try(TenantRouting.Binding ignored=tenants.open(company)){if(kick(company))queued++;}return map("queued_companies",queued);}
    public boolean kick(String company){TenantRouting.Route scope=tenants.capture(company);String key=scope.datasource()+"/"+company;requested.add(key);if(!active.add(key))return false;boolean submitted=executor.submit(scope,()->{requested.remove(key);try{run(company);}finally{active.remove(key);if(requested.remove(key))kick(company);}});if(!submitted){active.remove(key);requested.remove(key);}return submitted;}
    public Map<String,Object> submit(String company,Map<String,Object> input,String actor){long channel=number(input,"channel_id");Map<String,Object> cap=exchanges.capability(company,channel);require(number(cap,"read_enabled")==1&&Boolean.TRUE.equals(cap.get("can_query")),"店铺换货查询未就绪");String request=text(input,"request_key");require(request.matches("[A-Za-z0-9_-]{8,64}"),"请求标识无效，请刷新重试");String ids=text(input,"dispute_ids").trim();LocalDateTime end=LocalDateTime.now().withNano(0),start=end.minusDays(1);List<String> selected=new ArrayList<>();String mode="MANUAL";
        if(!ids.isEmpty()){mode="IDS";for(String id:ids.split("[\\s,，;；]+")){require(id.matches("[1-9][0-9]{0,63}"),"平台换货单号格式无效");if(!selected.contains(id))selected.add(id);}require(!selected.isEmpty()&&selected.size()<=20,"每次最多补全20个换货申请");}
        else{start=time(text(input,"start_time"));end=time(text(input,"end_time"));require(start.isBefore(end)&&!end.isAfter(LocalDateTime.now().plusMinutes(1))&&Duration.between(start,end).compareTo(Duration.ofDays(31))<=0,"请选择开始不晚于结束、最多31天的同步范围");}
        final LocalDateTime a=start,b=end;final String type=mode;long id=tx().execute(s->{repository.db().update("INSERT INTO oms_exchange_config(company_code,channel_id,initial_time,cursor_time,updated_by) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE channel_id=VALUES(channel_id)",company,channel,a.format(TIME),a.format(TIME),actor);repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel);List<Map<String,Object>> existing=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND request_key=?",ROW,company,channel,request);if(!existing.isEmpty()){Map<String,Object> old=existing.get(0);require(type.equals(text(old,"mode"))&&(type.equals("IDS")?strings(old.get("dispute_ids")).equals(selected):a.format(TIME).equals(text(old,"start_time"))&&b.format(TIME).equals(text(old,"end_time"))),"请求标识已用于其他同步范围");return number(old,"id");}repository.db().update("INSERT INTO oms_exchange_sync(company_code,channel_id,mode,start_time,end_time,dispute_ids,actor,request_key) VALUES (?,?,?,?,?,?,?,?)",company,channel,type,a.format(TIME),b.format(TIME),encode(selected),actor,request);long created=repository.db().queryForObject("SELECT id FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND request_key=?",Long.class,company,channel,request);if("IDS".equals(type)){repository.db().update("UPDATE oms_exchange_sync SET phase='DETAIL',page_complete=1 WHERE company_code=? AND id=?",company,created);for(String dispute:selected)repository.db().update("INSERT INTO oms_exchange_sync_item(company_code,task_id,dispute_id,result,message) VALUES (?,?,?,'PENDING','等待详情拉取')",company,created,dispute);}changed(company,created);return created;});return map("id",id,"state","PENDING");}
    public List<Map<String,Object>> tasks(String company){List<Map<String,Object>> rows=repository.db().query("SELECT id,channel_id,mode,start_time,end_time,page_no,phase,state,attempts,synced_count,new_count,updated_count,unchanged_count,failed_count,last_error,create_time FROM oms_exchange_sync WHERE company_code=? ORDER BY id DESC LIMIT 50",ROW,company);repository.messageProgress(company,rows,"EXCHANGE_PULL");return rows;}
    public Map<String,Object> task(String company,long id){List<Map<String,Object>> rows=repository.db().query("SELECT id,channel_id,mode,start_time,end_time,page_no,phase,state,attempts,synced_count,new_count,updated_count,unchanged_count,failed_count,last_error,actor,create_time FROM oms_exchange_sync WHERE company_code=? AND id=?",ROW,company,id);require(rows.size()==1,"换货同步任务不存在或无权访问");Map<String,Object> t=rows.get(0);repository.messageProgress(company,Collections.singletonList(t),"EXCHANGE_PULL");t.put("items",repository.db().query("SELECT i.dispute_id,i.result,i.message,i.platform_exchange_id,COALESCE(p.business_exchange_id,i.exchange_id) exchange_id,e.exchange_sn,e.state business_state FROM oms_exchange_sync_item i LEFT JOIN oms_platform_exchange p ON p.company_code=i.company_code AND p.id=i.platform_exchange_id LEFT JOIN oms_exchange e ON e.company_code=i.company_code AND e.id=COALESCE(p.business_exchange_id,i.exchange_id) WHERE i.company_code=? AND i.task_id=? ORDER BY i.id DESC LIMIT 100",ROW,company,id));t.put("item_count",repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_sync_item WHERE company_code=? AND task_id=?",Long.class,company,id));return t;}
    Map<String,Object> rawTask(String c,long id,boolean lock){List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND id=?"+(lock?" FOR UPDATE":""),ROW,c,id);require(rows.size()==1,"换货同步任务不存在或不属于当前公司");return rows.get(0);}
    void changed(String c,long id){if(repository.messaging()==null)return;Map<String,Object> t=rawTask(c,id,true);long v=number(t,"work_version");if(!repository.db().queryForList("SELECT id FROM oms_message_outbox WHERE company_code=? AND service_code='order' AND message_type='EXCHANGE_PULL' AND business_id=? AND business_version=? LIMIT 1",c,String.valueOf(id),v).isEmpty())return;repository.messaging().enqueue(c,"EXCHANGE_PULL",id,v,"EXCHSYNC"+id,id+":"+v,0);}
    public void retry(String c,long id){tx().execute(s->{Map<String,Object> hint=rawTask(c,id,false);repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,c,hint.get("channel_id"));Map<String,Object> t=rawTask(c,id,true);require(Arrays.asList("FAILED","RETRY").contains(text(t,"state")),"当前换货同步任务无需重试");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_config WHERE company_code=? AND channel_id=? AND lease_until>NOW()",Long.class,c,t.get("channel_id"))==0,"店铺正在处理，请稍后重试");repository.db().update("UPDATE oms_exchange_sync SET state='RETRY',attempts=0,work_version=work_version+1,next_attempt=NOW(),last_error='' WHERE company_code=? AND id=?",c,id);changed(c,id);return null;});}
    void fence(String c,long channel,String lease){require(!repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",ROW,c,channel,lease).isEmpty(),"换货同步租约已失效");}
    boolean claim(String c,long channel,String lease){return repository.db().update("UPDATE oms_exchange_config SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND channel_id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,channel)==1;}
    void release(String c,long channel,String lease){repository.db().update("UPDATE oms_exchange_config SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND channel_id=? AND lease_token=?",c,channel,lease);}
    Map<String,Object> config(String c,long channel){List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_exchange_config WHERE company_code=? AND channel_id=?",ROW,c,channel);require(rows.size()==1,"请先配置换货接入");return rows.get(0);}
    void run(String company){for(Map<String,Object> config:repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND ((enabled=1 AND next_run<=NOW()) OR EXISTS(SELECT 1 FROM oms_exchange_sync s WHERE s.company_code=oms_exchange_config.company_code AND s.channel_id=oms_exchange_config.channel_id AND s.state IN ('PENDING','RUNNING','RETRY') AND s.next_attempt<=NOW())) ORDER BY next_run,channel_id LIMIT 10",ROW,company))shop(company,number(config,"channel_id"));platformExchanges.autoConvert(company);execution.pollCompany(company);if(automatic!=null)automatic.scan(company);}
    void shop(String company,long channel){String lease=token();if(!claim(company,channel,lease))return;
        try{tx().execute(s->{fence(company,channel,lease);Map<String,Object> c=config(company,channel);List<Map<String,Object>> pending=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND state IN ('PENDING','RUNNING','RETRY') ORDER BY id LIMIT 20 FOR UPDATE",ROW,company,channel);
            if(pending.isEmpty()&&repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND mode='AUTO' AND state='FAILED' AND end_time>?",Long.class,company,channel,c.get("cursor_time"))==0&&number(c,"enabled")==1&&c.get("next_run")!=null&&!time(text(c,"next_run")).isAfter(LocalDateTime.now())){LocalDateTime start=time(text(c,"cursor_time")).minusMinutes(2),initial=time(text(c,"initial_time")),end=LocalDateTime.now().minusSeconds(3).withNano(0);if(start.isBefore(initial))start=initial;if(end.isAfter(start.plusDays(1)))end=start.plusDays(1);if(end.isAfter(start)){long id=repository.insert("INSERT INTO oms_exchange_sync(company_code,channel_id,mode,start_time,end_time,actor,request_key) VALUES (?,?,'AUTO',?,?,'定时任务',?)",company,channel,start.format(TIME),end.format(TIME),token());pending.add(rawTask(company,id,false));}repository.db().update("UPDATE oms_exchange_config SET next_run=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND channel_id=?",company,channel);}
            for(Map<String,Object> t:pending)changed(company,number(t,"id"));return null;});
        }finally{release(company,channel,lease);}}
    @PreDestroy public void close(){executor.close();}
}
